(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.TransformLesson,num=window.LinearLesson,ns='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function numberTex(x){return num.fractionTex(num.rational(Math.round(x*2),2));}
function formula(a,h,k){const input=h===0?'x':h>0?`(x-${h})`:`(x+${-h})`,factor=a===1?'':a===-1?'-':numberTex(a);return `g(x)=${factor}${input}^2`+(k===0?'':k>0?'+'+k:String(k));}
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [key,value] of Object.entries(attrs))e.setAttribute(key,value);parent.append(e);}
function tick(n,left,top){const e=document.createElement('span');e.className='transform-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#transform-ticks').append(e);}
for(let n=-5;n<=5;n++){const p=core.point(n,n);svg('line',{x1:p.x,x2:p.x,y1:30,y2:330},$('#transform-grid'));svg('line',{x1:30,x2:330,y1:p.y,y2:p.y},$('#transform-grid'));tick(n,p.x/3.6,53);if(n!==0)tick(n,47,p.y/3.6);}
function path(a,h,k){const points=[];for(let i=0;i<=240;i++){const x=-5+i/24,p=core.point(x,core.value(x,a,h,k));points.push(`${i===0?'M':'L'}${p.x} ${p.y}`);}return points.join(' ');}
$('#base-curve').setAttribute('d',path(1,0,0));
function draw(){const h=Number($('#shift-x').value),k=Number($('#shift-y').value),scale=Number($('#scale').value),a=$('#reflect').checked?-scale:scale,v=core.point(h,k),tracked=core.transform(1,1,a,h,k),t=core.point(tracked.x,tracked.y),r=core.range(a,k);$('#shift-x-output').value=h;$('#shift-y-output').value=k;$('#scale-output').value=scale;$('#changed-curve').setAttribute('d',path(a,h,k));for(const [id,p] of [['vertex-dot',v],['tracked-dot',t]]){document.getElementById(id).setAttribute('cx',p.x);document.getElementById(id).setAttribute('cy',p.y);}math($('#transform-equation'),formula(a,h,k));math($('#point-mapping'),`(1,1)\\longmapsto(${tracked.x},${numberTex(tracked.y)})`);math($('#transform-range'),`D=\\mathbb R,\\qquad R_g=${a>0?'['+k+',\\infty)':'(-\\infty,'+k+']'}`);$('#transform-feedback').innerHTML=`Pengali tegaknya <span data-tex="a=${numberTex(a)}"></span>. `+(a>0?'Parabola terbuka ke atas.':'Parabola terbuka ke bawah.')+` Puncaknya <span data-tex="(${h},${k})"></span>; nilai ${a>0?'terendah':'tertinggi'} adalah <span data-tex="${a>0?r.min:r.max}"></span>. `+(scale===1?'Jarak tegak dari puncak tidak berubah skalanya.':scale>1?'Jarak tegak dari puncak membesar dibandingkan grafik dasar pada jarak mendatar yang sama dari puncaknya.':'Jarak tegak dari puncak mengecil dibandingkan grafik dasar pada jarak mendatar yang sama dari puncaknya.');$('#transform-plot').setAttribute('aria-label',`Grafik dasar y sama dengan x kuadrat dan hasil transformasi dengan pengali ${a}, pergeseran mendatar ${h}, pergeseran tegak ${k}. Puncak (${h}, ${k}); titik dasar (1, 1) menjadi (${tracked.x}, ${tracked.y}).`);}
['shift-x','shift-y','scale'].forEach(id=>$('#'+id).addEventListener('input',draw));$('#reflect').addEventListener('change',draw);$('#reset-transform').addEventListener('click',()=>{$('#shift-x').value=0;$('#shift-y').value=0;$('#scale').value=1;$('#reflect').checked=false;draw();});draw();
const questions=[{tex:'(1,4)\\in\\text{grafik }f,\\quad g(x)=2f(x-3)-1',prompt:'Titik yang bersesuaian pada grafik baru memiliki koordinat mendatar berapa? Ini fungsi umum; titiknya tidak harus berasal dari kuadrat pada lab.',n:4,hint:'Koordinat mendatar lama ditambah pergeseran ke kanan.',why:'Isi fungsi kembali bernilai satu ketika masukan baru empat. Jadi koordinat mendatarnya empat.'},{tex:'(1,4)\\in\\text{grafik }f,\\quad g(x)=2f(x-3)-1',prompt:'Titik yang sama memiliki koordinat tegak baru berapa?',n:7,hint:'Kalikan koordinat tegak lama dengan dua, kemudian kurangi satu.',why:'Koordinat tegak lama empat dikalikan dua menjadi delapan, lalu dikurangi satu menjadi tujuh.'},{tex:'g(x)=(x+2)^2-3',prompt:'Berapa koordinat mendatar puncak parabola ini?',n:-2,hint:'Cari masukan yang membuat isi kuadrat nol.',why:'Masukan negatif dua membuat isi kuadrat nol. Puncaknya memiliki koordinat mendatar negatif dua dan koordinat tegak negatif tiga.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya -2.':'Belum tepat. Telusuri koordinat lama dan perubahan yang berlaku untuk arah itu.');}));
const choices=[{tex:'g(x)=-2(x-1)^2+3',prompt:'Dengan domain bilangan real, apa range fungsi ini?',options:['Semua bilangan real lebih besar dari atau sama dengan tiga.','Semua bilangan real lebih kecil dari atau sama dengan tiga.','Semua bilangan real.'],answer:1,why:'Kuadrat tidak negatif. Setelah dikali negatif dua dan ditambah tiga, hasilnya tidak lebih dari tiga. Batas tiga tercapai pada masukan satu.'},{tex:'g(x)=f(x+2)',prompt:'Bagaimana posisi grafik baru terhadap grafik semula?',options:['Dua satuan ke kiri.','Dua satuan ke kanan.','Dua satuan ke atas.'],answer:0,why:'Untuk mempertahankan isi fungsi, masukan baru harus dua lebih kecil daripada masukan lama. Setiap titik bergeser ke kiri.'},{tex:'g(x)=f(2x)',prompt:'Jika titik pada grafik semula mempunyai koordinat mendatar empat, berapa koordinat mendatar titik yang bersesuaian pada grafik baru?',options:['Delapan.','Empat.','Dua.'],answer:2,why:'Masukan baru dua membuat isi fungsi bernilai empat. Koordinat mendatarnya dibagi dua, bukan dikali dua.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-transform-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-transform-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();